    {
      "card_ids": ["C19"],
      "claim": "Tramadol has an absolute oral bioavailability of 68.4% in humans, supporting the high-F prediction despite moderate first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Methylene blue has an absolute bioavailability of 72.3 ± 23.9% in human participants, providing another direct human F measurement above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Thalidomide has probably high absolute oral bioavailability (80–100% at low doses) in fasting healthy volunteers, supporting high F for a structurally complex oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Deramciclane, despite the lowest transfer score among the major analogues, has an absolute bioavailability of 44.3 ± 8.6% in healthy volunteers, still clearly above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental analogues report oral bioavailability values well above 20%, including multiple direct absolute bioavailability measurements in humans (range approximately 36–100%). The highest-transfer analogues are uniformly supportive, and no evidence points to F < 20%. Therefore the query molecule is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
